head.script:
scwin.onpageload = async function() {
    console.log("session", "onpageload");
    //$c.session.sessionCheck();
};

/*
 * 사용자 정보 저장소.
 * 기존에는 scwin.js_id 처럼 개별 전역변수에 사용자 속성을 저장했으나,
 * 단일 JSON 객체(scwin.userInfo)로 저장/관리하도록 변경함. (scwin.setUserInfo 참고)
 *
 * 필드 구조(서버 응답 body와 동일):
 */
scwin.userInfo = {};

scwin.g_dev_stf_url = "https://dev-staff.krx.co.kr";
scwin.g_test_stf_url = "https://test-staff.krx.co.kr";
scwin.g_real_stf_url = "https://staff.krx.co.kr";

scwin.g_dev_kind_url = "http://dev-kind.krx.co.kr";
scwin.g_test_kind_url = "http://test-kind.krx.co.kr";

scwin.g_dev_filing_url = "https://dev-filing.krx.co.kr";
scwin.g_test_filing_url = "https://test-filing.krx.co.kr";

scwin.g_dev_rcv_url = "https://dev-rcv.krx.co.kr";
scwin.g_test_rcv_url = "https://test-rcv.krx.co.kr";
scwin.g_real_rcv_url = "https://rcv.krx.co.kr";

scwin.g_dev_manager_url = "https://dev-manager.krx.co.kr";
scwin.g_test_manager_url = "https://test-manager.krx.co.kr";
scwin.g_real_manager_url = "https://manager.krx.co.kr";

scwin.url = "/api/common/user-info";

/**
 * @method
 * @name sessionCheck
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.sessionCheck = async function() {
    if (!$p) {
        $p = $w;
    }

	const isLogin = await $c.session.isLogin();

    if (isLogin) {
        await $c.session.goIndex();
    } else {
		await $c.session.goLogin(true);
	}
};

/**
 * @method
 * @name getExcelDownPath
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.getExcelDownPath = function() {
    return (scwin.userInfo.accessTp == '1') ? 'k:\\개인 폴더\\' : 'c:\\staffDownload\\';
};

/**
 * @method
 * @name getUserInfo
 * @description 사용자 정보(scwin.userInfo) 전체 또는 지정한 필드 값을 반환합니다.
 * @param {String} [param] 조회할 필드명. 생략 시 사용자 정보 전체를 반환합니다.
 * @hidden N
 * @exception
 * @example
 *
 *  $c.session.getUserInfo();        // 사용자 정보 전체
 *  $c.session.getUserInfo("empNm"); // 사용자 이름
 */
scwin.getUserInfo = function(param) {
    if (!param) {
        console.log(scwin.userInfo);
        return scwin.userInfo;
    }
    console.log(scwin.userInfo[param]);
    return scwin.userInfo[param];
};

/**
 * @method
 * @name setUserInfo
 * @description 사용자 정보를 조회하여 scwin.userInfo(JSON)에 저장합니다.
 * @param
 * @returns {Promise<Boolean>} 사용자 정보 조회/저장 성공 여부
 * @hidden N
 * @exception
 * @example
 *
 *  await $c.session.setUserInfo();
 */
scwin.setUserInfo = async function() {
    try {
        let res = await fetch(scwin.url, { method: "GET" });
        let rslt = await res.json();

        if (!res.ok) {
            if (!rslt.success) {
                if (rslt.message.indexOf("인증이") > -1) {
                    console.log("로그인으로 갑니다.");
                    //$c.session.goLogin();
                } else {
                    console.log("다른 에러", rslt);
                }
            }
            return false;
        }

        if (rslt && rslt.success && rslt.body) {
            // 서버가 내려준 사용자 정보(JSON)를 그대로 보관한다.
            scwin.userInfo = rslt.body;
            return true;
        }
        return false;
    } catch (e) {
        console.log("사용자 정보 조회 실패", e);
        return false;
    }
};

/**
 * @method
 * @name isLogin
 * @description 로그인 여부를 확인한다.
 * @param
 * @returns {Boolean}
 * @hidden N
 * @exception
 * @example let isLogin = $c.session.isLogin();
 * if(isLogin){
 *  console.log("로그인이 되어 있습니다.");
 * }else{
 * console.log("로그인이 안 되어 있습니다.");
 * }
 */
scwin.isLogin = async function() {
	// 서버에서 로그인 정보가 있는 확인
	await $c.session.setUserInfo();

	return Object.keys(scwin.userInfo).length > 0;
};

/**
 * @method
 * @name goLogin
 * @description 로그인 페이지로 전환됩니다.
 * @param
 * @hidden N
 * @exception
 * @example
 *
 * $c.session.goLogin();
 *
 */
scwin.goLogin = async function(isRedirect = false) {
	// 로그인 여부를 확인해서 로그인 페이지로 이동
	let isLogin = false;

	if (!isRedirect) {
		isLogin = await $c.session.isLogin();
	}

	// 로그인 페이지이거나 로그인 상태면 return
    if (document.location.search === "" && isLogin) {
		await $c.session.goIndex();
		return;
	} else if (document.location.href.indexOf(`/cm/main/${WebSquareExternal.contextPath}/login.xml`) > -1) {
        return;
    } 

	// redirectUrl 이 있는 경우 해당 페이지로 이동
	if (!$c.util.isEmpty(WebSquareExternal.redirectUrl)) {
		await $p.main().pfm_main.setSrc(WebSquareExternal.redirectUrl);
		WebSquareExternal.redirectUrl = "";
		return;
	}

	if (!isLogin) {
		//await $c.win.alert("로그인 페이지로 이동합니다.");

		await $p.main().pfm_main.setSrc(`/cm/main/${WebSquareExternal.contextPath}/login.xml`);
		return;
	}
};

/**
 * @method
 * @name goIndex
 * @description Index 페이지로 전환됩니다.
 * @param
 * @hidden N
 * @exception
 * @example
 *
 * $c.session.goIndex();
 *
 */
scwin.goIndex = async function(isFirst = false) {
	if ($c.util.isEmpty(WebSquareExternal.redirectUrl)) {
		await $p.main().pfm_main.setSrc(`/cm/main/${WebSquareExternal.contextPath}/index.xml`);
	} else {
		await $p.main().pfm_main.setSrc(WebSquareExternal.redirectUrl);
		WebSquareExternal.redirectUrl = "";
	}

	return;
};

/**
 * @method
 * @name goLogout
 * @description 로그아웃 후 로그인 페이지로 전환됩니다.
 * @param
 * @hidden N
 * @exception
 * @example
 *
 * $c.session.goLogout();
 *
 */
scwin.goLogout = async function() {
	scwin.userInfo = {};
    await $p.main().pfm_main.setSrc(`/cm/main/${WebSquareExternal.contextPath}/login.xml`);
};
